// Copy between the rounded scaled edges, where rectangles sampling the copy are drawn. Rounding the
// width separately can leave the copy a pixel narrower than its rectangle at fractional scales.
const long scaledLeft = lround(fbTile.left * resolutionScale.x);
const long scaledTop = lround(fbTile.top * resolutionScale.y);
const uint32_t tileWidth = std::clamp<long>(lround(fbTile.right * resolutionScale.x) - scaledLeft, 1L, RenderTarget::MaxDimension);
const uint32_t tileHeight = std::clamp<long>(lround(fbTile.bottom * resolutionScale.y) - scaledTop, 1L, RenderTarget::MaxDimension);
